import sys,os
sys.path.insert(0, '/utils')
from common import check_and_download_file, check_file_in_owncloud_directory, get_gitlab_project_id, get_plane_project_id
out_dir = '/workspace/evidence/downloads'
os.makedirs(out_dir, exist_ok=True)
remote_dirs = ['/', '/Documents', '/Public', '/Shared', '/Runbooks', '/runbooks', '/Runbooks/Signed', '/runbooks/signed', '/Policies', '/Governance', '/runbooks/impact-assessment', '/Impact Assessments', '/Impact-Assessments', '/impact_assessments']
filenames = ['impact-assessment-rm.md','impact_assessment_rm.md','impact-assessment.md','impact_assessment.md','impact-assessment-rm']
results = []
for r in remote_dirs:
    for f in filenames:
        local = os.path.join(out_dir, (r.strip('/').replace(' ','_') or 'root') + '_' + f.replace('/','_'))
        try:
            ok = check_and_download_file(f, r, local)
            results.append((r,f,'OK' if ok else 'NOT_FOUND', local))
        except Exception as e:
            results.append((r,f,'ERROR', str(e)))
# Query GitLab and Plane for likely project names
git_names = ['runbooks','impact-assessments','impact-assessment-rm','ai-governance','ai_governance','the-agent-company','the_agent_company','agent-company','theagentcompany']
git_results = {}
for name in git_names:
    try:
        pid = get_gitlab_project_id(name)
        git_results[name] = pid
    except Exception as e:
        git_results[name] = f'ERROR: {e}'
plane_results = {}
for name in git_names:
    try:
        pp = get_plane_project_id(name)
        plane_results[name] = pp
    except Exception as e:
        plane_results[name] = f'ERROR: {e}'
# Print summary
print('OWNCLOUD CHECKS:')
for r,f,status,info in results:
    print(r, f, status, info)
print('\nGITLAB CHECKS:')
for k,v in git_results.items():
    print(k, v)
print('\nPLANE CHECKS:')
for k,v in plane_results.items():
    print(k, v)
# Save to evidence file
with open('/workspace/evidence/owncloud_git_plane_search.txt','w') as fh:
    fh.write('OWNCLOUD CHECKS:\n')
    for r,f,status,info in results:
        fh.write(f"{r}\t{f}\t{status}\t{info}\n")
    fh.write('\nGITLAB CHECKS:\n')
    for k,v in git_results.items():
        fh.write(f"{k}\t{v}\n")
    fh.write('\nPLANE CHECKS:\n')
    for k,v in plane_results.items():
        fh.write(f"{k}\t{v}\n")
print('\nSaved summary to /workspace/evidence/owncloud_git_plane_search.txt')
